lessons.example:
* { box-sizing: border-box; }
.card {
  width: min(100%, 28rem);
  padding: 1.5rem;
  border: 1px solid #d5dfeb;
  border-radius: 0.5rem;
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 1rem;
}
.toolbar { display: flex; align-items: center; gap: .75rem; }

.dialog { position: fixed; inset: 0; z-index: 20; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

const lessons = ["HTML", "CSS"];
function makeGreeting(name) {
  return `Welcome, ${name}!`;
}
const student = { name: "Ari", completed: 2 };
console.log(makeGreeting(student.name), lessons.length);

const form = document.querySelector('#signup');
form.addEventListener('submit', event => {
  event.preventDefault();
  const name = new FormData(form).get('name');
  document.querySelector('#message').textContent = `Thanks, ${name}!`;
});

async function loadCourses() {
  try {
    const response = await fetch('/api/courses');
    if (!response.ok) throw new Error('Could not load courses');
    return await response.json();
  } catch (error) {
    console.error(error);
    return [];
  }
}

const fs = require('fs/promises');
async function readSettings() {
  const text = await fs.readFile('./settings.json', 'utf8');
  return JSON.parse(text);
}
readSettings().then(console.log).catch(console.error);

const express = require('express');
const app = express();
app.use(express.json({ limit: '16kb' }));
app.post('/api/notes', (req, res) => {
  if (typeof req.body.title !== 'string' || !req.body.title.trim()) {
    return res.status(400).json({ error: 'A title is required.' });
  }
  res.status(201).json({ title: req.body.title.trim() });
});

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production' }
}));
